ee=Employees.FirstOrDefault(x=>x.Id==value.EmployeeId);EntryDate=value.Date;StartTimeText=value.StartTime.ToString(@"hh\:mm");EndTimeText=value.EndTime.ToString(@"hh\:mm");BreakMinutes=value.BreakMinutes;EntryComment=value.Comment??"";StatusMessage="";}partial void OnSelectedCalendarDayChanged(OperatingCalendarRow? value){if(value is null)return;CalendarDate=value.Date;CalendarName=value.Name;CalendarIsWorkingDay=value.IsWorkingDay;CalendarTargetHoursFactor=value.TargetHoursFactor;CalendarComment=value.Comment??"";StatusMessage="";}[RelayCommand]private void PreviousMonth()=>Month=Month.AddMonths(-1);[RelayCommand]private void CurrentMonth()=>Month=new(DateTime.Today.Year,DateTime.Today.Month,1);[RelayCommand]private void NextMonth()=>Month=Month.AddMonths(1);[RelayCommand]private void Refresh(){LoadEmployees();Load();ResetEditorsForMonth();StatusMessage="Arbeitszeit und Betriebskalender aktualisiert.";}[RelayCommand]private void NewEntry()=>ResetEntryEditor();private void ResetEditorsForMonth(){ResetEntryEditor();ResetCalendarEditor();}private void ResetEntryEditor(){SelectedEntry=null;EntryDate=DateTime.Today.Month==Month.Month&&DateTime.Today.Year==Month.Year?DateTime.Today:Month;StartTimeText="06:00";EndTimeText="14:00";BreakMinutes=30;EntryComment="";}private void ResetCalendarEditor(){SelectedCalendarDay=null;CalendarDate=DateTime.Today.Month==Month.Month&&DateTime.Today.Year==Month.Year?DateTime.Today:Month;CalendarName="";CalendarIsWorkingDay=false;CalendarTargetHoursFactor=0;CalendarComment="";}
 [RelayCommand]private void SaveEntry(){if(SelectedEmployee is null){StatusMessage="Bitte einen Mitarbeiter auswählen.";return;}if(!TryParseClock(StartTimeText,out var start)||!TryParseClock(EndTimeText,out var end)){StatusMessage="Start und Ende bitte exakt als HH:mm (00:00–23:59) eingeben.";return;}if(start==end){StatusMessage="Start und Ende dürfen nicht identisch sein. Eine 24-Stunden-Buchung ist nicht zulässig.";return;}if(BreakMinutes<0||BreakMinutes>240){StatusMessage="Pause muss zwischen 0 und 240 Minuten liegen.";return;}var duration=end>start?end-start:end.Add(TimeSpan.FromDays(1))-start;if(TimeSpan.FromMinutes(BreakMinutes)>=duration){StatusMessage="Die Pause muss kürzer als die Arbeitszeit sein.";return;}if(duration-TimeSpan.FromMinutes(BreakMinutes)<TimeSpan.FromMinutes(15)){StatusMessage="Nach Abzug der Pause müssen mindestens 15 Minuten Arbeitszeit verbleiben.";return;}using var db=new AppDbContext();var candidate=GetInterval(EntryDate.Date,start,end);var other=db.WorkTimeEntries.AsNoTracking().Where(x=>x.EmployeeId==SelectedEmployee.Id&&x.Date.Date>=EntryDate.Date.AddDays(-1)&&x.Date.Date<=EntryDate.Date.AddDays(1)).ToList();if(SelectedEntry is not null)other=other.Where(x=>x.Id!=SelectedEntry.Id).ToList();var conflict=other.FirstOrDefault(x=>IntervalsOverlap(candidate,GetInterval(x.Date,x.StartTime,x.EndTime)));if(conflict is not null){StatusMessage=$"Arbeitszeit überschneidet sich mit einem bestehenden Eintrag vom {conflict.Date:dd.MM.yyyy} ({conflict.StartTime:hh\\:mm}–{conflict.EndTime:hh\\:mm}). Speichern wurde abgebrochen.";return;}WorkTimeEntry e;if(SelectedEntry is null){e=new();db.WorkTimeEntries.Add(e);}else e=db.WorkTimeEntries.First(x=>x.Id==SelectedEntry.Id);e.EmployeeId=SelectedEmployee.Id;e.Date=EntryDate.Date;e.StartTime=start;e.EndTime=end;e.BreakMinutes=BreakMinutes;e.Comment=string.IsNullOrWhiteSpace(EntryComment)?null:EntryComment.Trim();db.SaveChanges();if(EntryDate.Year!=Month.Year||EntryDate.Month!=Month.Month)Month=new(EntryDate.Year,EntryDate.Month,1);else Load(e.Id);StatusMessage="Arbeitszeit gespeichert.";}private static bool TryParseClock(string? text,out TimeSpan value)=>TimeSpan.TryParseExact(text?.Trim(),@"hh\:mm",CultureInfo.InvariantCulture,out value)&&value>=TimeSpan.Zero&&value<TimeSpan.FromDays(1);private static(DateTime Start,DateTime End)GetInterval(DateTime date,TimeSpan start,TimeSpan end){var a=date.Date+start;var b=date.Date+end;if(b<=a)b=b.AddDays(1);return(a,b);}private static bool IntervalsOverlap((DateTime Start,DateTime End)a,(DateTime Start,DateTime End)b)=>a.Start<b.End&&b.Start<a.End;
 [RelayCommand]private void DeleteEntry(){if(SelectedEntry is null)return;using var db=new AppDbContext();var e=db.WorkTimeEntries.FirstOrDefault(x=>x.Id==SelectedEntry.Id);if(e is null)return;RecycleBinService.ArchiveDeletion(db,e,e.Id.ToString(),$"Arbeitszeit {SelectedEntry.EmployeeName} · {e.Date:dd.MM.yyyy} · {e.StartTime:hh\\:mm}–{e.EndTime:hh\\:mm}");db.WorkTimeEntries.Remove(e);db.SaveChanges();Load();ResetEntryEditor();StatusMessage="Arbeitszeit entfernt und im Papierkorb archiviert.";}[RelayCommand]private void NewCalendarDay()=>ResetCalendarEditor();[RelayCommand]private void SaveCalendarDay(){if(string.IsNullOrWhiteSpace(CalendarName)){StatusMessage="Bitte eine Bezeichnung eingeben.";return;}if(!double.IsFinite(CalendarTargetHoursFactor)||CalendarTargetHoursFactor<0||CalendarTargetHoursFactor>2){StatusMessage="Sollstunden-Faktor muss eine gültige Zahl zwischen 0 und 2 sein.";return;}if(!CalendarIsWorkingDay)CalendarTargetHoursFactor=0;using var db=new AppDbContext();var same=db.OperatingCalendarDays.FirstOrDefault(x=>x.Date.Date==CalendarDate.Date);OperatingCalendarDay e;if(SelectedCalendarDay is null){e=same??new();if(same is null)db.OperatingCalendarDays.Add(e);}else{e=db.OperatingCalendarDays.First(x=>x.Id==SelectedCalendarDay.Id);if(same is not null&&same.Id!=e.Id){StatusMessage="Für dieses Datum existiert bereits eine Betriebskalender-Ausnahme.";return;}}e.Date=CalendarDate.Date;e.Name=CalendarName.Trim();e.IsWorkingDay=CalendarIsWorkingDay;e.TargetHoursFactor=CalendarIsWorkingDay?CalendarTargetHoursFactor:0;e.Comment=string.IsNullOrWhiteSpace(CalendarComment)?null:CalendarComment.Trim();db.SaveChanges();if(CalendarDate.Year!=Month.Year||CalendarDate.Month!=Month.Month)Month=new(CalendarDate.Year,CalendarDate.Month,1);else Load(calendarSelectId:e.Id);StatusMessage="Betriebskalender gespeichert.";}[RelayCommand]private void DeleteCalendarDay(){if(SelectedCalendarDay is null)return;using var db=new AppDbContext();var e=db.OperatingCalendarDays.FirstOrDefault(x=>x.Id==SelectedCalendarDay.Id);if(e is null)return;RecycleBinService.ArchiveDeletion(db,e,e.Id.ToString(),$"Betriebskalender {e.Date:dd.MM.yyyy} · {e.Name}");db.OperatingCalendarDays.Remove(e);db.SaveChanges();Load();ResetCalendarEditor();StatusMessage="Kalender-Ausnahme entfernt und im Papierkorb archiviert; es gilt wieder der Standard Mo–Fr.";}
 private void LoadEmployees(){var id=SelectedEmployee?.Id;using var db=new AppDbContext();Employees.Clear();foreach(var x in db.Employees.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.LastName).ThenBy(x=>x.FirstName))Employees.Add(new(){Id=x.Id,DisplayName=$"{x.LastName}, {x.FirstName}",Role=x.Role});SelectedEmployee=Employees.FirstOrDefault(x=>x.Id==id)??Employees.FirstOrDefault();}private void Load(int? entrySelectId=null,int? calendarSelectId=null){using var db=new AppDbContext();var start=Month.Date;var end=start.AddMonths(1).AddDays(-1);var entries=db.WorkTimeEntries.AsNoTracking().Include(x=>x.Employee).Where(x=>x.Date.Date>=start&&x.Date.Date<=end).AsEnumerable().OrderBy(x=>x.Date).ThenBy(x=>x.StartTime).ThenBy(x=>x.Employee.LastName).ToList();Entries.Clear();foreach(var x in entries)Entries.Add(new(){Id=x.Id,EmployeeId=x.EmployeeId,Date=x.Date,DateText=x.Date.ToString("ddd dd.MM."),EmployeeName=$"{x.Employee.LastName}, {x.Employee.FirstName}",StartTime=x.StartTime,EndTime=x.EndTime,TimeText=$"{x.StartTime:hh\\:mm}–{x.EndTime:hh\\:mm}",BreakMinutes=x.BreakMinutes,NetHours=OperatingCalendarService.CalculateNetHours(x.StartTime,x.EndTime,x.BreakMinutes),Comment=x.Comment});var employees=db.Employees.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.LastName).ThenBy(x=>x.FirstName).ToList();var planned=db.PlanningAssignments.AsNoTracking().Where(x=>x.Date.Date>=start&&x.Date.Date<=end).ToList();var calendar=db.OperatingCalendarDays.AsNoTracking().Where(x=>x.Date.Date>=start&&x.Date.Date<=end).OrderBy(x=>x.Date).ToList();var map=calendar.ToDictionary(x=>x.Date.Date);Balances.Clear();foreach(var e in employees){var target=OperatingCalendarService.GetTargetHours(e,start,end,map);var actual=entries.Where(x=>x.EmployeeId==e.Id).Sum(x=>OperatingCalendarService.CalculateNetHours(x.StartTime,x.EndTime,x.BreakMinutes));var ph=planned.Where(x=>x.EmployeeId==e.Id).Sum(x=>OperatingCalendarService.CalculateNetHours(x.StartTime,x.EndTime,x.BreakMinutes));Balances.Add(new(){